from pathlib import Path
import subprocess,json,hashlib,time,statistics,fcntl
p=Path(__file__).parent;root=p.parent;official=Path('/tmp/sirkit_duf_20261022/official');base=(p/'baseline.cpp').read_text();template=(root/'baseline_submission.cpp').read_text();tags=['baseline','full','split','schedule'];rows=[];builds=[];checks=[]
for compiler in ['gcc','clang']:
 cxx=['g++']if compiler=='gcc'else['clang++','--gcc-install-dir=/opt/atcoder/gcc/lib/gcc/x86_64-pc-linux-gnu/15.3.0']
 for tag in tags:
  source=(p/(tag+'.cpp')).read_text();src=p/(compiler+'_'+tag+'.cpp');assert base in template;src.write_text(template.replace(base,source));binary=src.with_suffix('');cmd=['taskset','-c','4',*cxx,'-std=c++23','-O2','-march=native','-Wall','-Wextra','-Wpedantic',str(src),'-o',str(binary)];v=subprocess.run(cmd,capture_output=True,text=True);assert not v.returncode,v.stderr;builds.append(dict(compiler=compiler,tag=tag,command=cmd,warnings=v.stderr,source_sha256=hashlib.sha256(source.encode()).hexdigest()))
  for case in sorted((official/'in').glob('*.in')):
   with case.open('rb')as f:v=subprocess.run([str(binary)],stdin=f,capture_output=True)
   assert not v.returncode,v.stderr;assert v.stdout.split()==(official/'out'/(case.stem+'.out')).read_bytes().split();checks.append(dict(compiler=compiler,tag=tag,case=case.stem,status='PASS'))
 control=p/(compiler+'_control');control.write_bytes((p/(compiler+'_baseline')).read_bytes());control.chmod(0o755)
print('golden',len(checks),'PASS',flush=True);(p/'checks.json').write_text(json.dumps(dict(builds=builds,checks=checks),indent=2))
with open('/tmp/atcoder_full_performance_20261018/benchmark.lock','a')as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 for compiler in ['gcc','clang']:
  for case in ['max_random_00','max_random_02','path_00','path_03']:
   for rep in range(-1,9):
    order=['baseline','control',*tags[1:]];i=(rep+1)%len(order);order=order[i:]+order[:i]
    if rep%2:order.reverse()
    for tag in order:
     with (official/'in'/(case+'.in')).open('rb')as f:start=time.perf_counter_ns();v=subprocess.run(['taskset','-c','14',str(p/(compiler+'_'+tag))],stdin=f,stdout=subprocess.DEVNULL,stderr=subprocess.PIPE);ns=time.perf_counter_ns()-start
     assert not v.returncode,v.stderr
     if rep>=0:rows.append(dict(compiler=compiler,case=case,rep=rep,tag=tag,ns=ns))
   rr=[x for x in rows if x['compiler']==compiler and x['case']==case];med={tag:round(statistics.median(x['ns']for x in rr if x['tag']==tag)/1e6,4)for tag in ['baseline','control',*tags[1:]]};print(compiler,case,med,flush=True);(p/'results.json').write_text(json.dumps(dict(rows=rows),indent=2))

