 cxx=['g++']if compiler=='gcc'else['clang++','--gcc-install-dir=/opt/atcoder/gcc/lib/gcc/x86_64-pc-linux-gnu/15.3.0']
 for tag in ['baseline','soa']:
  source=p/(tag+'_seeded.cpp');binary=p/(compiler+'_'+tag+'_seeded');cmd=['taskset','-c','10',*cxx,'-std=c++23','-O2','-march=native','-DSKIP_RUNTIME_CHECKS','-Wall','-Wextra','-Wpedantic','-DDUF_SOURCE="'+str(source)+'"','/tmp/sirkit_duf_20261022/opt/stack/api.cpp','-o',str(binary)];v=subprocess.run(cmd,capture_output=True,text=True);assert not v.returncode,v.stderr;builds.append(dict(compiler=compiler,tag=tag,command=cmd,warnings=v.stderr,source_sha256=hashlib.sha256(source.read_bytes()).hexdigest()))
 control=p/(compiler+'_control_seeded');control.write_bytes((p/(compiler+'_baseline_seeded')).read_bytes());control.chmod(0o755)
print('built controlled-seed API benchmark',flush=True)
with open('/tmp/atcoder_full_performance_20261018/benchmark.lock','a')as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 for compiler in ['gcc','clang']:
  for n in [32,200000]:
   for mode in ['dense_add','sparse_add','read_dense','read_sparse']:
    for rep in range(-1,7):
     order=tags[:];i=(rep+1)%len(order);order=order[i:]+order[:i]
     if rep%2:order.reverse()
     seed=seeds[max(rep,0)];env=os.environ.copy();env['DUF_BENCH_SEED']=str(seed)
     for tag in order:
      v=subprocess.run(['taskset','-c','14',str(p/(compiler+'_'+tag+'_seeded')),mode,str(n)],capture_output=True,text=True,env=env);assert not v.returncode,v.stderr;ns,checksum,nodes=map(int,v.stdout.split())
      if rep>=0:rows.append(dict(compiler=compiler,n=n,mode=mode,rep=rep,seed=seed,tag=tag,ns=ns,checksum=checksum,nodes=nodes))
