    med={tag:statistics.median(x['ns']for x in rr if x['tag']==tag)/1e6 for tag in tags};ratios=[]
    for rep in range(7):
     sample={x['tag']:x['ns']for x in rr if x['rep']==rep};ratios.append(sample['soa']/sample['baseline'])
    print(compiler,n,mode,{k:round(v,4)for k,v in med.items()},'pairedmedian',round((statistics.median(ratios)-1)*100,2),flush=True);(p/'seeded_api_results.json').write_text(json.dumps(dict(builds=builds,seeds=seeds,method='Only test header initial_salt clock changed to getenv/strtoull(DUF_BENCH_SEED), mix(seed)|1 retained; seed paired within replicate; production binaries untouched.',rows=rows),indent=2))

